MHE_CH8 = {"label": "Angrist & Pischke (2009), Mostly Harmless Econometrics, Ch. 8 — Nonstandard Standard Error Issues", "url": "https://www.degruyterbrill.com/document/doi/10.1515/9781400829828-013/html"}
MIT_MHE = {"label": "MIT OpenCourseWare — Applied Econometrics: Mostly Harmless Big Data, readings", "url": "https://ocw.mit.edu/courses/14-387-applied-econometrics-mostly-harmless-big-data-fall-2014/pages/readings/"}
