PSU_DESIGN = {"label": "Penn State STAT 509, Lesson 8 — Sample Size and Power", "url": "https://online.stat.psu.edu/stat509/Lesson08.html"}
NIST_SAMPLE = {"label": "NIST/SEMATECH e-Handbook — Sample Sizes Required for a Mean", "url": "https://www.itl.nist.gov/div898/handbook/prc/section2/prc222.htm"}
MHE_CH2 = {"label": "Angrist & Pischke (2009), Mostly Harmless Econometrics, Ch. 2 — The Experimental Ideal", "url": "https://www.degruyterbrill.com/document/doi/10.1515/9781400829828-007/html"}
MIXTAPE_CH4 = {"label": "Cunningham, Causal Inference: The Mixtape, Ch. 4 — Potential Outcomes and Randomization", "url": "https://mixtape.scunning.com/04-potential_outcomes_and_randomization"}
UN_MEASUREMENT = {"label": "United Nations Statistics Division — Measurement Error in Household Surveys", "url": "https://unstats.un.org/unsd/hhsurveys/pdf/chapter_9.pdf"}
ROS = {"label": "Regression and Other Stories — authors’ book site and chapter resources", "url": "https://sites.stat.columbia.edu/gelman/regression/"}
MHE_CH3 = {"label": "Angrist & Pischke (2009), Mostly Harmless Econometrics, Ch. 3 — Making Regression Make Sense", "url": "https://www.degruyterbrill.com/document/doi/10.1515/9781400829828-008/html"}
BLS_CPI = {"label": "U.S. Bureau of Labor Statistics — Consumer Price Index: Concepts and Calculation", "url": "https://www.bls.gov/opub/hom/cpi/concepts.htm"}
BLS_CALC = {"label": "U.S. Bureau of Labor Statistics — CPI Calculation", "url": "https://www.bls.gov/opub/hom/cpi/calculation.htm"}
EUROSTAT = {"label": "Eurostat — Harmonised Index of Consumer Prices Methodological Manual (2024)", "url": "https://ec.europa.eu/eurostat/web/products-manuals-and-guidelines/w/ks-gq-24-003"}

new_modules = [
    module(
        "bootstrap-inference", "Bootstrap Inference & Resampling", "Resampling & Inference", "Beginner–Intermediate", 36, "bootstrap",
        "Use repeated resamples to study the uncertainty of statistics—while respecting how people, places or time periods entered the data.",
        ["Construct a bootstrap distribution by sampling observed units with replacement.",
         "Use bootstrap variation to describe standard errors and approximate confidence intervals.",
         "Read a resample trace and histogram, and choose a resampling unit that reflects the study design."],
        [
            lesson("Resample the data you have", "Choose the statistic that answers the question first: a median wage, a difference in employment rates or a regression slope. The population distribution is unknown, so the ordinary nonparametric bootstrap uses the observed sample's empirical distribution as a stand-in. Penn State STAT 555's process graphic makes the steps visible: sample, empirical-population approximation, computer resamples, then a distribution of the recomputed statistic. Draw n units with replacement, recompute T, and repeat. Reused rows are not new people; bootstrapping cannot repair a biased sample or reveal the unobserved population.", "The empirical distribution stands in for an unknown population only under stated sampling assumptions."),
            lesson("Read spread and intervals from the bootstrap distribution", "The standard deviation of bootstrap estimates is a bootstrap standard error. A percentile interval uses quantiles of the bootstrap distribution as approximate confidence limits. For example, the central 95% interval is bounded by its 2.5th and 97.5th percentiles. These are methods for estimating uncertainty, not a guarantee that a particular interval contains the population value. Bias, skew, small samples and the chosen interval method can matter; compare a bootstrap interval with a defensible analytic alternative when one is available.", "A bootstrap interval is an approximation whose method and assumptions should be reported.", formula="Bootstrap SE = SD(T*₁, …, T*ᴮ); percentile interval = [Q₂.₅%(T*), Q₉₇.₅%(T*)]."),
            lesson("Match resampling to the data structure", "Resampling individual rows assumes those rows are exchangeable independent sampling units. If workers were sampled within a small set of districts, resample whole primary sampling units or use design-provided replicate weights rather than treating every worker as independent. For a time series, random row resampling destroys serial order; a block or model-based method may be needed. A bootstrap calculation is only as credible as its representation of how the data were collected.", "The resampling unit follows the sampling design and dependence structure, not the spreadsheet row by default."),
            lesson("Choose a bootstrap model and inspect its output", "The nonparametric bootstrap resamples observed cases; a parametric bootstrap simulates from a fitted distribution; some semiparametric methods resample and add carefully justified smoothing noise. These are different assumptions, not interchangeable buttons. A trace plot places each replicate's statistic against its replicate number, as in NIST's bootstrap-plot teaching graphic; a histogram then reveals the distribution's shape and tail spread. Check for Monte Carlo instability, skew, boundaries and statistics that depend heavily on unobserved tails. More repetitions smooth computation, not missing information.", "State how the population was approximated; use a trace plot for replicate stability and a histogram for distribution shape."),
            lesson("Connect bootstrap intervals to econometric inference", "An estimated coefficient or median difference also needs an uncertainty calculation that respects the units and dependence in the study. If policy is assigned at a small number of districts, resampling individuals independently may make the interval too narrow. Angrist and Pischke's discussion of nonstandard standard errors and MIT's applied-econometrics reading list are useful follow-up reading on clustering and serial dependence; bootstrap methods still need their own design justification and do not automatically solve small-cluster inference.", "Clustering-aware inference is a design issue; a bootstrap does not fix too few independent assignment units."),
            lesson("Apply it to a regional wage comparison", "A labour analyst wants to compare median hourly earnings between two regions, where earnings are skewed and group sizes differ. Resample workers separately within each region, calculate the median difference on every repetition, and summarize the resulting distribution. If workers were selected through a complex survey or grouped by sampled areas, the replication must reflect that design. The interval describes sampling uncertainty conditional on the observed data and assumptions; it does not remove nonresponse or establish why regional wages differ.", "A useful bootstrap case still needs a clear target population and a defensible sample design.", practice={"question":"In an ordinary bootstrap for n sampled workers, how is each resample formed?", "hint":"Think about the sample size and whether a worker can appear more than once.", "solution":"Draw n workers with replacement from the observed sample. A worker may appear multiple times or not at all in a given resample."})
        ],
        "A regional labour survey reports a median-wage gap. A bootstrap can show how that median difference varies across resamples, but the analyst must preserve any survey strata or sampled-area clustering and still discuss coverage and nonresponse separately.",
        ["A bootstrap does not generate new population information beyond the observed sample.", "A percentile interval is not guaranteed to work well for every statistic or small sample.", "Resampling individual rows is not appropriate when the design or dependence structure requires resampling clusters or time blocks.", "Increasing the number of repetitions cannot remove selection bias or measurement error."],
        [NIST_BOOT, PSU_BOOT, HESTERBERG, MHE_CH8, MIT_MHE],
        {"question":"What does an ordinary nonparametric bootstrap sample do?", "options":["Draws the observed units with replacement, usually keeping the original sample size", "Selects a fresh random sample from the unknown population", "Permutes treatment labels to impose a null hypothesis"], "answerIndex":0, "explanation":"The ordinary bootstrap resamples the observed data with replacement. A permutation test is a different procedure, and neither one repairs a biased original sample."}
    ),
    module(
        "statistical-power-planning", "Statistical Power & Sample-Size Planning", "Study Planning", "Beginner–Intermediate", 34, "powerplan",
        "Plan a study around a meaningful economic effect, outcome variability, significance level and the number of genuinely independent units.",
        ["Define the causal target and a minimum economically important effect before looking at results.",
         "Explain how effect size, variability, significance level and sample size shape power.",
         "Separate power-based testing plans from precision-based interval plans, and treat both as conditional scenarios."],
        [
            lesson("Start with a decision-relevant causal target", "Before calculating sample size, specify the population, treatment or policy contrast, outcome, follow-up horizon and effect that would matter to a decision. In potential-outcomes language, the causal target compares outcomes under two possible treatment states for the target group; random assignment gives a credible comparison in expectation, but each unit reveals only one state. This connects to the research-design logic in Mostly Harmless Econometrics, Chapter 2, and the potential-outcomes/randomization framework in Mixtape, Chapter 4. Power is about precision for this target—not proof that assignment, measurement or follow-up is valid.", "Define the estimand and assignment mechanism before asking how many observations are needed."),
            lesson("Choose a precision target or a power target", "Sample size can be planned to make a confidence interval sufficiently narrow, or to attain a chosen probability of rejecting a null at a meaningful alternative; these are related but distinct goals. Penn State's clinical-trial notes illustrate the two routes and show how a normal-curve cutoff separates type-I error, type-II error and power. For a two-sided equal-arm mean comparison, a simple normal approximation gives n per arm ≈ 2(z₁₋α/₂ + z₁₋β)²σ²/δ². This formula assumes independent groups and a defensible SD and effect; NIST likewise emphasizes that there is no unique sample-size answer without assumptions. Report those inputs rather than treating the output as a universal number.", "A planned power value is conditional on the assumed alternative, model and test; precision planning instead targets interval width.", formula="n per group ≈ 2 × (z₁₋α/₂ + z₁₋β)² × σ² / δ² (two-sided, equal independent groups)."),
            lesson("Distinguish power from the minimum detectable effect", "If the sample is already fixed, a minimum-detectable-effect calculation asks how large a true difference must be to reach a chosen power under the stated model. If a policy-relevant effect is fixed, a power calculation asks how often the design would detect it. Neither quantity says that an undetected effect is zero. A wide interval can include meaningful gains and losses, so report planned precision and later uncertainty—not only whether a p-value crosses a threshold.", "Power and minimum detectable effect answer related but different planning questions."),
            lesson("Account for assignment, clustering and attrition", "A nominal count of people is not necessarily the number of independent units. Cluster assignment, shared shocks, unequal allocation, repeated measures and a limited number of sites can change the standard error and the relevant design degrees of freedom. Anticipated attrition may require recruiting more units, but multiplying by an attrition factor does not fix selective outcome loss. Plan for primary outcomes and subgroup contrasts, and avoid quietly searching many outcomes for one favourable result.", "Count the independent assignment or sampling units, and model realistic loss and multiplicity."),
            lesson("Power cannot repair a weak design", "A very large sample can estimate a biased comparison very precisely. Power calculations address random variation under a model; they do not remove confounding from non-random assignment, selective attrition, spillovers, a poorly measured outcome or a mismatch between the study population and policy target. Mostly Harmless Econometrics' experimental-ideal chapter and Mixtape's potential-outcomes chapter treat assignment and the causal comparison as design questions. Ask whether the estimate identifies the target effect before celebrating its standard error.", "More observations reduce sampling noise; they do not substitute for a credible comparison."),
            lesson("Plan a job-training evaluation", "Suppose an employment agency wants to detect a pre-specified wage gain among eligible jobseekers. Use pilot wages to estimate variation, choose the smallest worthwhile gain, and compare power at realistic sample sizes. This mirrors the design-first logic in economic experiments: in Mixtape's discussion of random assignment, an experimental contrast is meaningful because the assignment mechanism supports a potential-outcomes comparison, not because a p-value is small. If training is assigned by centre, plan using the centre-level assignment structure; show sensitivity to effect size and attrition. The result is a scenario, not a promise that a future estimate will be significant.", "A credible plan documents its causal target, assumptions and sensitivity to plausible scenarios.", practice={"question":"Under a simple design, what usually increases power if all else is unchanged?", "hint":"More observations reduce sampling uncertainty, but how should the count be interpreted when units share a cluster?", "solution":"More independent observations usually increase power. When units share assignment or shocks within clusters, the number and dependence of clusters must also be considered."})
        ],
        "An agency considers a job-training trial at employment centres. It defines a worthwhile wage gain, uses pilot information for outcome variation, plans enough centres and participants for the assignment design, and presents power across several plausible effects rather than promising a positive finding.",
        ["A study with low power does not prove that the true effect is zero.", "Power is not the probability that the alternative hypothesis is true.", "A larger individual count does not replace having enough independent clusters when assignment is clustered.", "Retrospective power computed from the observed effect is not a substitute for an uncertainty interval."],
        [PSU_POWER, PSU_DESIGN, NIST_SAMPLE, MHE_CH2, MIXTAPE_CH4],
        {"question":"What is the clearest interpretation of 80% power at a specified effect?", "options":["Under the stated model, the test rejects about 80% of the time if that effect is true", "There is an 80% probability that the study's alternative hypothesis is true", "The study will estimate the true effect within 20%"], "answerIndex":0, "explanation":"Power is a repeated-sampling probability conditional on the specified effect, design, test and assumptions."}
    ),
    module(
        "measurement-error-economics", "Measurement Error in Economic Data", "Data Quality", "Beginner–Intermediate", 36, "measurement",
        "Separate the economic concept of interest from its observed proxy, and learn why noisy or systematic measurements can change estimates and decisions.",
        ["Distinguish a latent concept, its recorded measure and the measurement error.",
         "Explain attenuation under classical error in a regressor and why other errors can behave differently.",
         "Identify validation, repeated-measurement and survey-design approaches for assessing measurement quality."],
        [
            lesson("Name the concept and the recorded variable", "An analyst may care about usual weekly hours, household income or local access to jobs, while the dataset contains a recalled survey answer, an administrative code or a geographic proxy. The recorded value is not automatically the concept itself. Measurement error is the discrepancy between what the method records and the intended quantity; it can be random, systematically directional or related across respondents. Define units, reference periods and operational rules before fitting a model.", "A variable name is not a measurement definition; document how the observation was produced."),
            lesson("Classical predictor error can flatten a slope", "In a simple linear model, let the observed predictor be X* = X + u, where u has mean zero and is independent of the true X and the outcome disturbance. The regression slope on X* is then attenuated toward zero by the reliability ratio Var(X)/(Var(X)+Var(u)). Angrist and Pischke discuss this regression problem in Chapter 3 of Mostly Harmless Econometrics; the key lesson is conditional, not a slogan that every error shrinks every estimate. With multiple regressors or non-classical errors, the direction can differ. Reliability also needs evidence, often a repeat or validation sample.", "Attenuation is the classical single-regressor result; check the model before applying it.", formula="X* = X + u; simple-regression slope factor = Var(X) / [Var(X) + Var(u)]."),
            lesson("Outcome error and non-classical error differ", "Independent, mean-zero noise in an outcome often increases residual variance without biasing a correctly specified linear-regression slope, whereas error in a predictor can bias the slope under the classical assumptions. Systematic under-reporting, proxy variables, coding changes or error correlated with income, treatment or unobserved determinants violate those assumptions and may bias estimates in either direction. Shared interviewer or administrative processing errors can also correlate observations. Always state which variable is measured with error and what is assumed about that error.", "The direction and size of bias depend on where error enters and how it relates to the true variables and disturbances."),
            lesson("Use data collection and validation to learn about error", "Question wording, respondent recall, interview mode and data processing can each contribute to survey measurement error. Cognitive interviews, randomized question wording, reinterviews and comparisons with administrative records can reveal some discrepancies. A validation subsample can estimate reliability under its own coverage and record-linkage assumptions. Repeated reports may contain shared errors, and an administrative record is not automatically error-free. Describe the validation target and uncertainty rather than treating one source as truth without argument.", "Measurement quality can be investigated, but comparison records and repeats also have limitations."),
            lesson("Interpret a commuting-time regression carefully", "A regional economist relates commute time to job access using a travel survey. Respondents may round durations, exclude transfers or report usual rather than yesterday's trips; the recorded measure can differ systematically by mode or work schedule. The analyst documents the question and units, checks repeat or route-based validation data, and tests sensitivity to plausible error. Better measurement may improve precision and interpretation, but a more reliable variable does not itself eliminate confounding or identify a causal effect.", "A better measured association is still an association unless the research design supports a causal claim.", practice={"question":"Under classical additive error in a single regressor, what is the usual effect on its simple-regression slope?", "hint":"The observed predictor includes independent noise in addition to its true variation.", "solution":"The slope is attenuated toward zero by the reliability ratio, provided the classical-error assumptions hold."})
        ],
        "A labour-market study uses self-reported commuting time to explain job access. The analyst checks the question's reference period, compares a validation subsample with route or administrative information, and reports how measurement limitations affect the interpretation without treating validation records as perfect.",
        ["Measurement error is not always random or mean-zero.", "Attenuation toward zero is not guaranteed outside the classical predictor-error model.", "Independent outcome noise and predictor error do not generally have the same regression consequence.", "An administrative record, proxy or validation measure can itself contain error."],
        [UN_MEASUREMENT, MHE_CH3, ROS],
        {"question":"When is the simple attenuation result for a noisy predictor most directly applicable?", "options":["When additive predictor error is mean-zero and independent of the true predictor and outcome disturbance", "Whenever any variable in any model is measured imperfectly", "Only when the outcome is a binary variable"], "answerIndex":0, "explanation":"The toward-zero result relies on the classical additive-error assumptions for a single regressor. Other measurement processes can produce different biases."}
    ),
    module(
        "price-indices-real-values", "Price Indices & Real Economic Values", "Economic Measurement", "Beginner–Intermediate", 34, "priceindex",
        "Build a weighted price index, interpret its base period and use it to distinguish changes in nominal amounts from changes in purchasing power.",
        ["Interpret price relatives, expenditure weights and an index normalized to a base value of 100.",
         "Calculate inflation from an index change and explain why index levels are not direct cross-place price comparisons.",
         "Deflate nominal wages or expenditure with a compatible price index and state what the result represents."],
        [
            lesson("An index summarizes a defined basket", "A consumer price index tracks price change for a specified population, set of items, geographic area and time period. A basket combines prices with expenditure or quantity weights, so a price change in a frequently purchased category can matter more than the same change in a rarely purchased item. The index is a summary for its stated scope; different households can experience different inflation because their baskets differ. State the population, coverage and base period when interpreting a series.", "An index measures price change for a defined basket and population, not every person's cost of living."),
            lesson("Understand the base and the weights", "A fixed-basket Laspeyres index compares the cost of a base-period basket at current prices with its cost at base-period prices, then multiplies by 100. A base value of 100 is a normalization, not a currency amount. Official indexes may use multistage aggregation, updated expenditure weights, quality adjustments or chained formulas, so a simple classroom formula is not a full description of an official CPI. Read the statistical agency's methodology for the series you use.", "The simple weighted-basket formula teaches the principle; official index construction may be more detailed.", formula="Laspeyres price indexₜ = 100 × Σᵢ(pᵢₜqᵢ₀) / Σᵢ(pᵢ₀qᵢ₀)."),
            lesson("Calculate inflation from changes in the index", "If a compatible index rises from 120 to 126, the price-index change is 5% because (126/120 − 1) × 100 = 5%. The index level of 126 does not mean prices are 26% higher than in another country with an index of 100, because the countries may use different baskets, populations and base periods. For long histories, chaining and rebasing help connect periods, but published definitions, revisions and seasonal-adjustment status still matter.", "Inflation is a percent change in a specified index over a specified interval."),
            lesson("Convert nominal values into real values", "A nominal wage records the currency amount paid; a real wage adjusts that amount for a chosen price index. When both are index numbers on compatible bases, a simple real-wage index is 100 times the nominal-wage index divided by the price index. This exact ratio can differ from the shortcut of subtracting inflation from nominal growth, especially for larger changes. The resulting series is purchasing-power-adjusted under the selected deflator; it is not a complete measure of welfare or an individual household's experienced prices.", "Deflation is a choice of price index and reference period, not a data-free transformation.", formula="Real valueₜ = nominal valueₜ / (price indexₜ / 100)."),
            lesson("Compare pay with prices in an education example", "Suppose a college instructor's nominal salary index rises from 100 to 104 while the relevant price index rises from 100 to 106. The real salary index is 104/106 × 100, or about 98.1, so measured purchasing power fell about 1.9% relative to the chosen base basket. A national CPI may be a useful deflator but may not match the instructor's housing, transport or childcare costs. Explain the chosen index and avoid calling it a personalized cost-of-living measure.", "Real-value claims are conditional on the deflator and its coverage.", practice={"question":"A nominal wage index is 104 and a price index is 106 on the same base. What is the real wage index?", "hint":"Divide the nominal index by the price index expressed relative to 100.", "solution":"100 × 104/106 ≈ 98.1. Relative to a base of 100, the real wage index is about 1.9% lower."})
        ],
        "A university tracks lecturer pay against a consumer price index. If nominal salaries rise by 4% while the chosen CPI rises by 6%, the exact real-wage index ratio shows a decline in purchasing power relative to that CPI basket; it does not describe every lecturer's personal expenses.",
        ["An index value of 100 is a base-period convention, not a price level in currency.", "Different regions' index levels cannot automatically be compared as if they were the cost of identical baskets.", "A CPI is not an exact cost-of-living measure for every household.", "Nominal growth minus inflation is an approximation; exact real growth uses an index ratio."],
        [BLS_CPI, BLS_CALC, EUROSTAT],
        {"question":"A price index rises from 120 to 126. What is the percentage change over that interval?", "options":["5%", "6%", "26%"], "answerIndex":0, "explanation":"The change is 126/120 − 1 = 0.05, or 5%. The index level itself is not the inflation rate."}
    ),
]

for item in new_modules:
    if item["id"] not in by_id:
        modules.append(item)
        by_id[item["id"]] = item
    else:
        # This script is the authored source of truth for these four new modules.
        # Reapply its full definitions so edits remain visible after every `pnpm seed`.
        index = next(i for i, existing in enumerate(modules) if existing["id"] == item["id"])
        modules[index] = item

DATA.write_text(json.dumps(modules, ensure_ascii=False, indent=2) + "\n")
print(f"Added applied statistics modules: {len(modules)} total modules, {sum(len(item.get('lessons', [])) for item in modules)} lessons.")
